package com.yeyamo_mobile.api.payment_service.infrastructure.webhook;
import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.payment_service.application.PaymentApplicationService;import com.yeyamo_mobile.api.payment_service.domain.PaymentException;
@Service public class PaymentWebhookService{
 private final ObjectMapper mapper;private final WebhookSignatureVerifier verifier;private final WebhookReceiptRepository receipts;private final PaymentApplicationService payments;private final String expectedProvider;
 public PaymentWebhookService(ObjectMapper m,WebhookSignatureVerifier v,WebhookReceiptRepository r,PaymentApplicationService p,@Value("${payment.provider.name}")String provider){mapper=m;verifier=v;receipts=r;payments=p;expectedProvider=provider;}
 @Transactional public void process(String provider,String timestamp,String signature,String raw)throws Exception{if(!expectedProvider.equals(provider))throw new PaymentException("INVALID_WEBHOOK_PROVIDER","Unexpected payment provider");verifier.verify(timestamp,signature,raw);JsonNode event=mapper.readTree(raw);String id=required(event,"eventId"),hash=sha256(raw);var replay=receipts.findByProviderAndProviderEventId(provider,id);if(replay.isPresent()){if(!replay.get().getPayloadHash().equals(hash))throw new PaymentException("WEBHOOK_REPLAY_CONFLICT","Webhook event identity was reused with a different payload");return;}var receipt=new WebhookReceiptEntity(provider,id,hash);receipts.save(receipt);String correlation=text(event,"correlationId");JsonNode payload=event.path("payload");switch(required(event,"type")){case"authorization.succeeded"->payments.providerAuthorizationSucceeded(required(payload,"providerPaymentId"),decimal(payload,"amount"),text(payload,"currency"),correlation);case"authorization.failed"->payments.providerAuthorizationFailed(required(payload,"providerPaymentId"),optional(payload,"reason","Provider declined authorization"),correlation);case"refund.succeeded"->payments.providerRefundSucceeded(required(payload,"providerRefundId"),correlation);case"refund.failed"->payments.providerRefundFailed(required(payload,"providerRefundId"),optional(payload,"reason","Provider refund failed"),correlation);default->{}}receipt.processed();receipts.save(receipt);}
 private String sha256(String raw)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String optional(JsonNode n,String f,String d){String v=text(n,f);return v==null||v.isBlank()?d:v;}private java.math.BigDecimal decimal(JsonNode n,String f){String v=text(n,f);return v==null||v.isBlank()?null:new java.math.BigDecimal(v);}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}
}
